package ru.murad.yourmarket.service;import org.junit.jupiter.api.Test;import ru.murad.yourmarket.model.Advertisement;import ru.murad.yourmarket.service.impl.ModerationServiceImpl;import ru.murad.yourmarket.telegram.TelegramGateway;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class ModerationServiceTest {ModerationTransactionService tx=mock(ModerationTransactionService.class);AdvertisementPublicationService pub=mock(AdvertisementPublicationService.class);TelegramGateway tg=mock(TelegramGateway.class);ModerationServiceImpl service=new ModerationServiceImpl(tx,pub,tg);UUID id=UUID.randomUUID(),op=UUID.randomUUID();Advertisement ad=Advertisement.builder().id(id).build();
@Test void mediaProgressSavedBeforeAction(){when(tx.claimSubmission(id)).thenReturn(new ModerationTransactionService.SubmitClaim(ad,op,true,null));when(tg.sendModerationMedia(ad)).thenReturn(List.of(1,2));when(tg.sendModerationAction(ad)).thenReturn(3);assertEquals(3,service.submit(id));var order=inOrder(tg,tx);order.verify(tg).sendModerationMedia(ad);order.verify(tx).saveModerationMedia(id,op,List.of(1,2));order.verify(tg).sendModerationAction(ad);order.verify(tx).completeSubmission(id,op,3);}
@Test void actionFailureBecomesUnknownNotResent(){when(tx.claimSubmission(id)).thenReturn(new ModerationTransactionService.SubmitClaim(ad,op,true,null)).thenReturn(new ModerationTransactionService.SubmitClaim(ad,null,false,null));when(tg.sendModerationMedia(ad)).thenReturn(List.of(1));when(tg.sendModerationAction(ad)).thenThrow(new RuntimeException());assertThrows(RuntimeException.class,()->service.submit(id));service.submit(id);verify(tg,times(1)).sendModerationMedia(ad);verify(tx).markSubmissionUnknown(id,op);}
@Test void retryAfterManualReconciliationDoesNotDuplicateSavedMedia(){when(tx.claimSubmission(id)).thenReturn(new ModerationTransactionService.SubmitClaim(ad,op,true,null));when(tx.hasSavedMedia(id)).thenReturn(true);when(tg.sendModerationAction(ad)).thenReturn(7);assertEquals(7,service.submit(id));verify(tg,never()).sendModerationMedia(any());verify(tx).completeSubmission(id,op,7);}}
